@@ -9264,8 +9264,9 @@ ssl_dissect_hnd_hello_common(ssl_common_dissect_t *hf, tvbuff_t *tvb, packet_inf
         if (ssl) {
             /* save the authoritative SID for later use in ChangeCipherSpec.
