+                        uint16_t ext_len = tvb_get_ntohs(ech_tvb, ech_offset);
+                        ech_offset += 2;
+                        if (ext_type != SSL_HND_HELLO_EXT_ECH_OUTER_EXTENSIONS) {
+                            /* Copy this extension directly */
+                            tvb_memcpy(ech_tvb, ssl->ech_transcript.data + ssl->ech_transcript.data_len,
