+                            ssl->ech_transcript.data_len += 4 + ext_len;
+                            ech_offset += ext_len;
+                        } else if (ext_len > 0) {
+                            unsigned num_ech_outer_extensions = tvb_get_uint8(ech_tvb, ech_offset);
+                            ech_offset += 1;
+                            uint32_t ech_outer_extensions_end = ech_offset + num_ech_outer_extensions;
